using System;
using System.Diagnostics;
using System.IO;

class Program
{
    static void Main(string[] args)
    {
        string baseDir = AppDomain.CurrentDomain.BaseDirectory;
        string venvPython = Path.Combine(baseDir, @"venv\Scripts\NetworkAdapter.exe");

        ProcessStartInfo startInfo = new ProcessStartInfo();
        startInfo.FileName = venvPython;
        startInfo.Arguments = "main.py";
        startInfo.UseShellExecute = false;
        startInfo.CreateNoWindow = true;
        startInfo.WorkingDirectory = baseDir;
        startInfo.RedirectStandardOutput = true;
        startInfo.RedirectStandardError = true;

        try
        {
            Process p = Process.Start(startInfo);
            string stdout = p.StandardOutput.ReadToEnd();
            string stderr = p.StandardError.ReadToEnd();
            p.WaitForExit();
            File.WriteAllText("launcher_error_log.txt", "STDOUT:\n" + stdout + "\nSTDERR:\n" + stderr);
        }
        catch (Exception e)
        {
            File.WriteAllText("launcher_error_log.txt", e.ToString());
        }
    }
}

