/* ===== SPECTRA — EXECUTIVE STEALTH & TITANIUM UI ===== */
/* Minimalist, high-contrast, distraction-free technical design */

:root {
    /* === TITANIUM & OBSIDIAN PALETTE === */
    --pure-black: #08090d;
    --pure-white: #f3f4f8;
    --charcoal: #0e0f14;
    --steel-gray: #15171f;
    --slate-panel: #1b1d27;
    --silver: #e2e4ea;
    --light-gray: #a2a5b5;

    /* === ACCENTS (Muted Technical) === */
    --accent-blue: #3b82f6;
    --accent-blue-light: #60a5fa;
    --accent-emerald: #10b981;
    --accent-amber: #f59e0b;
    --accent-rose: #f43f5e;
    --accent-cyan: #0ea5e9;

    /* === SEMANTIC MAP === */
    --bg-primary: #090a0e;
    --bg-secondary: #111218;
    --bg-tertiary: #171821;
    --bg-card: #14151e;
    --bg-glass: rgba(13, 14, 20, 0.92);
    --bg-glass-light: rgba(20, 21, 29, 0.75);
    --text-primary: #f0f1f6;
    --text-secondary: #9093a3;
    --text-muted: #5e6172;
    --border-color: rgba(255, 255, 255, 0.08);
    --border-hover: rgba(255, 255, 255, 0.16);
    --border-glow: rgba(59, 130, 246, 0.22);
    --accent-primary: #3b82f6;
    --accent-success: #10b981;
    --accent-warning: #f59e0b;
    --accent-glow: rgba(59, 130, 246, 0.10);

    /* === SPACING === */
    --space-xs: 4px;
    --space-sm: 8px;
    --space-md: 16px;
    --space-lg: 24px;
    --space-xl: 32px;

    /* === TYPOGRAPHY === */
    --font-xs: 12px;
    --font-sm: 13px;
    --font-base: 15px;
    --font-lg: 19px;
    --font-xl: 22px;
    --font-2xl: 28px;
    --font-mono: 'JetBrains Mono', 'Fira Code', 'SF Mono', 'Monaco', monospace;

    /* === MOTION === */
    --transition-fast: 0.15s cubic-bezier(0.4, 0, 0.2, 1);
    --transition-base: 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    --radius-sm: 6px;
    --radius-md: 9px;
    --radius-lg: 12px;
    --radius-pill: 999px;
}

/* ===== BASE ===== */
* {
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background: var(--bg-primary);
    color: var(--text-primary);
    margin: 0;
    padding: 0;
    min-height: 100vh;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-size: var(--font-base);
    line-height: 1.5;
    display: flex;
    flex-direction: column;
}

