    --border-glow: rgba(99, 102, 241, 0.35);
    --accent-primary: var(--accent-indigo);
    --accent-success: var(--success-green);
    --accent-warning: var(--warning-orange);
    --accent-glow: rgba(99, 102, 241, 0.12);

    /* === SPACING === */
    --space-xs: 4px;
    --space-sm: 8px;
    --space-md: 16px;
    --space-lg: 24px;
    --space-xl: 32px;

    /* === TYPOGRAPHY === */
