    font-weight: 600;
    text-transform: none;
    letter-spacing: 0.02em;
    color: var(--text-secondary);
    background: var(--bg-tertiary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-pill);
    cursor: pointer;
    transition: all var(--transition-fast);
    vertical-align: middle;
    line-height: 1.6;
}

