private const string LogPath = @"C:\Users\Arthur Henrique\Documents\GitHub\Spectra\spectra_debug.log";

public MainWindow()
{
    InitializeComponent();
    Closing += (s, e) => File.AppendAllText(LogPath, $"MainWindow Closing fired! Cancel={e.Cancel}\n");
    Closed += MainWindow_Closed;
    Loaded += MainWindow_Loaded;
}

private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
{
    var helper = new WindowInteropHelper(this);
    IntPtr hwnd = helper.Handle;

    // Initialize Win32 window management (Capture protection, click-through, transparency)
    _windowManager.Initialize(hwnd);
    _hotkeyManager.Initialize(hwnd);
    RegisterGlobalHotkeys();

    // Hook HwndSource to receive WM_HOTKEY messages
    var source = HwndSource.FromHwnd(hwnd);
    source.AddHook(WndProc);

    // Connect SessionController events to UI
    _sessionController.SendToUi += (type, payload) =>
    {
        Dispatcher.Invoke(() =>
        {
            SendJsonToWeb(type, payload);
        });
    };

    File.AppendAllText(LogPath, $"MainWindow Loaded at {DateTime.UtcNow}\n");

    // Initialize WebView2
    await InitializeWebViewAsync();
}

private async Task InitializeWebViewAsync()
{
    try
    {
        var env = await CoreWebView2Environment.CreateAsync(null, Path.Combine(Path.GetTempPath(), "Spectra_WebView2_Profile"));
        await WebView.EnsureCoreWebView2Async(env);

        string webFolder = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "web");
        if (!Directory.Exists(webFolder))
        {
            webFolder = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "..", "..", "..", "web");
        }

        webFolder = Path.GetFullPath(webFolder);
        WebView.CoreWebView2.SetVirtualHostNameToFolderMapping(
            "spectra.local",
            webFolder,
            CoreWebView2HostResourceAccessKind.Allow
        );

        WebView.CoreWebView2.WebMessageReceived += CoreWebView2_WebMessageReceived;
        WebView.CoreWebView2.Settings.AreDevToolsEnabled = Settings.Instance.DevMode;

        await WebView.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync(@"
            window.addEventListener('error', (e) => {
                window.chrome.webview.postMessage({ type: 'js_error', payload: { message: e.message, filename: e.filename, lineno: e.lineno } });
            });
        ");

        WebView.CoreWebView2.ProcessFailed += (s, args) =>
        {
            File.AppendAllText(LogPath, $"WebView2 ProcessFailed: {args.ProcessFailedKind}, Reason={args.Reason}\n");
        };

        WebView.NavigationCompleted += (s, args) =>
        {
            File.AppendAllText(LogPath, $"WebView2 NavigationCompleted: Success={args.IsSuccess}, ErrorStatus={args.WebErrorStatus}\n");
        };

        File.AppendAllText(LogPath, $"Setting up WebView2 with folder: {webFolder}\n");
        WebView.Source = new Uri("https://spectra.local/index.html");
        File.AppendAllText(LogPath, "WebView2 source set successfully\n");
    }
    catch (Exception ex)
    {
        File.AppendAllText(LogPath, $"WebView2 Init Exception: {ex}\n");
        System.Windows.MessageBox.Show($"Failed to initialize WebView2: {ex.Message}", "Error", MessageBoxButton.OK, MessageBoxImage.Error);
    }
}

