private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
{
    try
    {
        File.AppendAllText(LogPath, $"[START MainWindow_Loaded] at {DateTime.UtcNow}\n");
        var helper = new WindowInteropHelper(this);
        IntPtr hwnd = helper.Handle;
        File.AppendAllText(LogPath, $"[HWND] {hwnd}\n");

        _windowManager.Initialize(hwnd);
        File.AppendAllText(LogPath, $"[WindowManager] Initialized\n");

        _hotkeyManager.Initialize(hwnd);
        File.AppendAllText(LogPath, $"[HotkeyManager] Initialized\n");

        RegisterGlobalHotkeys();
        File.AppendAllText(LogPath, $"[Hotkeys] Registered\n");

        var source = HwndSource.FromHwnd(hwnd);
        if (source != null)
        {
            source.AddHook(WndProc);
            File.AppendAllText(LogPath, $"[HwndSource] Hook added\n");
        }

        _sessionController.SendToUi += (type, payload) =>
        {
            Dispatcher.Invoke(() =>
            {
                SendJsonToWeb(type, payload);
            });
        };

        await InitializeWebViewAsync();
        File.AppendAllText(LogPath, $"[MainWindow_Loaded] Complete!\n");
    }
    catch (Exception ex)
    {
        File.AppendAllText(LogPath, $"[LOAD ERROR] {ex}\n");
    }
}

