private async Task InitializeWebViewAsync()
{
    try
    {
        File.AppendAllText(LogPath, "[WebView2] Configuring CreationProperties\n");
        WebView.CreationProperties = new Microsoft.Web.WebView2.Wpf.CoreWebView2CreationProperties
        {
            UserDataFolder = Path.Combine(Path.GetTempPath(), "Spectra_WebView2_Profile")
        };

        File.AppendAllText(LogPath, "[WebView2] Calling EnsureCoreWebView2Async\n");
        await WebView.EnsureCoreWebView2Async();
        File.AppendAllText(LogPath, "[WebView2] EnsureCoreWebView2Async returned successfully\n");

        string exeDir = Path.GetDirectoryName(Environment.ProcessPath) ?? AppDomain.CurrentDomain.BaseDirectory;
        string webFolder = Path.Combine(exeDir, "web");
        if (!Directory.Exists(webFolder)) webFolder = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "web");
        if (!Directory.Exists(webFolder)) webFolder = Path.Combine(exeDir, "..", "web");
        if (!Directory.Exists(webFolder)) webFolder = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "..", "..", "..", "web");

        webFolder = Path.GetFullPath(webFolder);
        File.AppendAllText(LogPath, $"[WebView2] Resolved webFolder (Exists={Directory.Exists(webFolder)}): {webFolder}\n");

        WebView.CoreWebView2.SetVirtualHostNameToFolderMapping(
            "spectra.local",
            webFolder,
            CoreWebView2HostResourceAccessKind.Allow
        );

        WebView.CoreWebView2.WebMessageReceived += CoreWebView2_WebMessageReceived;
        WebView.CoreWebView2.Settings.AreDevToolsEnabled = Settings.Instance.DevMode;

        await WebView.CoreWebView2.AddScriptToExecuteOnDocumentCreatedAsync(@"
            window.addEventListener('error', (e) => {
                window.chrome.webview.postMessage({ type: 'js_error', payload: { message: e.message, filename: e.filename, lineno: e.lineno } });
            });
        ");

        WebView.CoreWebView2.ProcessFailed += (s, args) =>
        {
            File.AppendAllText(LogPath, $"[WebView2 ProcessFailed] {args.ProcessFailedKind}, Reason={args.Reason}\n");
        };

        WebView.NavigationCompleted += (s, args) =>
        {
            File.AppendAllText(LogPath, $"[WebView2 NavigationCompleted] Success={args.IsSuccess}, ErrorStatus={args.WebErrorStatus}\n");
        };

        File.AppendAllText(LogPath, $"[WebView2] Navigating to https://spectra.local/index.html\n");
        WebView.CoreWebView2.Navigate("https://spectra.local/index.html");
