private void RegisterGlobalHotkeys()
{
    // Alt+Z: Toggle Visibility
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Z, () =>
    {
        Dispatcher.Invoke(() => _windowManager.ToggleVisibility());
    });

    // Alt+X: Toggle Ghost Mode
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.X, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _windowManager.ToggleGhostMode();
            SendJsonToWeb("ghost_mode_toggled", new { is_ghost = _windowManager.IsGhostMode });
        });
    });

    // Alt+1/2/3: Transparency Presets (Number Row + Numpad)
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.D1, () => SetWindowOpacity(0.40));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.D2, () => SetWindowOpacity(0.70));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.D3, () => SetWindowOpacity(1.00));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.NumPad1, () => SetWindowOpacity(0.40));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.NumPad2, () => SetWindowOpacity(0.70));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.NumPad3, () => SetWindowOpacity(1.00));

    // Alt+[ and Alt+]: Step transparency down/up
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.OemOpenBrackets, () => AdjustTransparency(-0.15));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.OemCloseBrackets, () => AdjustTransparency(+0.15));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Oem4, () => AdjustTransparency(-0.15));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Oem6, () => AdjustTransparency(+0.15));

    // Alt+Q/W/E: AI Presets (Primary, Secondary, Auto)
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Q, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Llm.ActivePreset = "primary";
            SendJsonToWeb("preset_switched", new { preset = "primary" });
        });
    });
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.W, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Llm.ActivePreset = "secondary";
            SendJsonToWeb("preset_switched", new { preset = "secondary" });
        });
    });
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.E, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Llm.ActivePreset = "auto";
            SendJsonToWeb("preset_switched", new { preset = "auto" });
        });
    });

    // Alt+S: Capture Screenshot
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.S, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Vision.CaptureScreen();
            SendJsonToWeb("screenshot_queued", new { count = _sessionController.Vision.QueueCount });
        });
    });

    // Alt+P: Process Screenshots with AI
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.P, () =>
    {
        Dispatcher.Invoke(async () =>
        {
            await _sessionController.ProcessVisionAnalysisAsync("", "", new List<string>());
        });
    });

    // Alt+R: Reset Screenshot Queue
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.R, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Vision.ClearQueue();
            SendJsonToWeb("screenshot_queued", new { count = 0 });
        });
    });

    // Alt+T: Switch Vision Model
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.T, () =>
    {
        Dispatcher.Invoke(() =>
        {
            SendJsonToWeb("switch_vision_model", new { });
        });
    });

    // Alt+M: Toggle Mic Mute
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.M, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.Audio.IsMuted = !_sessionController.Audio.IsMuted;
            SendJsonToWeb("mute_state_changed", new { is_muted = _sessionController.Audio.IsMuted });
        });
    });

    // Alt+U: Toggle Universal Mute (Pause)
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.U, () =>
    {
        Dispatcher.Invoke(() =>
        {
            SendJsonToWeb("toggle_universal_mute", new { });
        });
    });

    // Alt+O: Reset Interview Session
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.O, () =>
    {
        Dispatcher.Invoke(() =>
        {
            _sessionController.ResetSession();
            SendJsonToWeb("session_reset", new { status = "ok" });
        });
    });

    // Movement Hotkeys: Alt+I/J/Left/Right
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.I, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(0, -20)));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.J, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(0, 20)));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Left, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(-20, 0)));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Right, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(20, 0)));

    // Scroll Hotkeys: Alt+Up/Down
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Up, () => ScrollWebContent(-100));
    _hotkeyManager.Register(NativeMethods.MOD_ALT, Keys.Down, () => ScrollWebContent(100));
}

private void ScrollWebContent(int deltaY)
{
    Dispatcher.Invoke(() =>
    {
        if (WebView != null && WebView.CoreWebView2 != null)
        {
            WebView.CoreWebView2.ExecuteScriptAsync($"window.scrollBy({{ top: {deltaY}, behavior: 'smooth' }});");
        }
    });
}

