private IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam)
{
    if (nCode >= 0 && (wParam == (IntPtr)WM_KEYDOWN || wParam == (IntPtr)WM_SYSKEYDOWN))
    {
        var hookStruct = Marshal.PtrToStructure<KBDLLHOOKSTRUCT>(lParam);
        Keys key = (Keys)hookStruct.vkCode;

        bool isSysKey = (wParam == (IntPtr)WM_SYSKEYDOWN);
        bool hasAltFlag = (hookStruct.flags & 0x20) != 0;
        bool isAltPressed = (GetAsyncKeyState(VK_MENU) & 0x8000) != 0;
        bool alt = isSysKey || hasAltFlag || isAltPressed;

        bool ctrl = (GetAsyncKeyState(VK_CONTROL) & 0x8000) != 0;
        bool shift = (GetAsyncKeyState(VK_SHIFT) & 0x8000) != 0;

        // Match exact (alt, ctrl, shift, key) or fallback without ctrl/shift constraints if not required
        if (_actions.TryGetValue((alt, ctrl, shift, key), out var action) ||
            (!ctrl && !shift && _actions.TryGetValue((alt, false, false, key), out action)))
        {
            try
            {
                string logPath = @"C:\Users\Arthur Henrique\Documents\GitHub\Spectra\spectra_debug.log";
                System.IO.File.AppendAllText(logPath, $"[HOTKEY TRIGGERED] Key={key}, Alt={alt}, Ctrl={ctrl}, Shift={shift}\n");
                action?.Invoke();
            }
            catch (Exception ex)
            {
                Debug.WriteLine($"Hotkey execution error: {ex.Message}");
            }
            return (IntPtr)1; // Consume key
        }
    }

    return CallNextHookEx(_hookId, nCode, wParam, lParam);
}

