    {
        // Native WPF Opacity now handles transparency (AllowsTransparency="True")
        // We no longer call SetLayeredWindowAttributes to avoid conflicts.
        _currentTransparency = opacity;
        return true;
    }
    catch
    {
        return false;
    }
}

