        private const int WM_SYSKEYDOWN = 0x0104;
        private const int VK_MENU = 0x12;
        private const int VK_CONTROL = 0x11;
        private const int VK_SHIFT = 0x10;
        private const uint LLKHF_ALTDOWN = 0x20;

        [StructLayout(LayoutKind.Sequential)]
        private struct KBDLLHOOKSTRUCT
        {
            public uint vkCode;
            public uint scanCode;
            public uint flags;
            public uint time;
            public IntPtr dwExtraInfo;
        }

        private delegate IntPtr LowLevelKeyboardProc(int nCode, IntPtr wParam, IntPtr lParam);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr SetWindowsHookEx(int idHook, LowLevelKeyboardProc lpfn, IntPtr hMod, uint dwThreadId);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        [return: MarshalAs(UnmanagedType.Bool)]
        private static extern bool UnhookWindowsHookEx(IntPtr hhk);

        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr CallNextHookEx(IntPtr hhk, int nCode, IntPtr wParam, IntPtr lParam);

        [DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        private static extern IntPtr GetModuleHandle(string? lpModuleName);

        [DllImport("user32.dll")]
        private static extern short GetAsyncKeyState(int vKey);

        // CRITICAL: Static reference prevents GC from collecting the delegate
        private static LowLevelKeyboardProc? _staticProc;
        private static GCHandle _gcHandle;

        private IntPtr _hookId = IntPtr.Zero;
        private readonly Dictionary<Keys, Action> _altActions = new();
        private readonly string _logPath;
        private Action<Action>? _dispatcher;

        public HotkeyManager()
        {
            string exeDir = Path.GetDirectoryName(Environment.ProcessPath) ?? AppDomain.CurrentDomain.BaseDirectory;
            _logPath = Path.Combine(exeDir, "spectra_debug.log");
        }

        private void Log(string msg)
        {
            try { File.AppendAllText(_logPath, $"{msg}\n"); } catch { }
        }

        public void Initialize(IntPtr hwnd, Action<Action>? dispatcher = null)
        {
            if (_hookId != IntPtr.Zero) return;

            _dispatcher = dispatcher;

            // Create delegate and pin it so GC cannot collect it
            _staticProc = HookCallback;
            _gcHandle = GCHandle.Alloc(_staticProc);

            // Use null module handle — works for all .NET app types including single-file
            IntPtr moduleHandle = GetModuleHandle(null);
            _hookId = SetWindowsHookEx(WH_KEYBOARD_LL, _staticProc, moduleHandle, 0);

            int error = Marshal.GetLastWin32Error();
            Log($"[HotkeyManager] SetWindowsHookEx result: hookId={_hookId}, moduleHandle={moduleHandle}, lastError={error}");

            if (_hookId == IntPtr.Zero)
            {
                Log("[HotkeyManager] FAILED to install keyboard hook!");
            }
            else
            {
                Log("[HotkeyManager] Low-level keyboard hook installed successfully");
            }
        }

        /// <summary>
        /// Register an Alt+Key shortcut. Only Alt modifier is supported for simplicity.
        /// </summary>
        public void Register(uint modifiers, Keys key, Action action)
        {
            _altActions[key] = action;
        }

        private IntPtr HookCallback(int nCode, IntPtr wParam, IntPtr lParam)
        {
            try
            {
                if (nCode >= 0 && (wParam == (IntPtr)WM_KEYDOWN || wParam == (IntPtr)WM_SYSKEYDOWN))
                {
                    var hookStruct = Marshal.PtrToStructure<KBDLLHOOKSTRUCT>(lParam);
                    Keys key = (Keys)hookStruct.vkCode;

                    // Detect Alt: via WM_SYSKEYDOWN, LLKHF_ALTDOWN flag, or async key state
                    bool alt = (wParam == (IntPtr)WM_SYSKEYDOWN)
                            || (hookStruct.flags & LLKHF_ALTDOWN) != 0
                            || (GetAsyncKeyState(VK_MENU) & 0x8000) != 0;

                    // Skip modifier keys themselves
                    if (key == Keys.LMenu || key == Keys.RMenu || key == Keys.Menu ||
                        key == Keys.LShiftKey || key == Keys.RShiftKey || key == Keys.ShiftKey ||
                        key == Keys.LControlKey || key == Keys.RControlKey || key == Keys.ControlKey)
                    {
                        return CallNextHookEx(_hookId, nCode, wParam, lParam);
                    }

                    if (alt && _altActions.TryGetValue(key, out var action))
                    {
                        // CRITICAL: Never block inside the hook callback.
                        // Fire the action on a thread pool thread to return instantly.
                        var capturedAction = action;
                        ThreadPool.QueueUserWorkItem(_ =>
                        {
                            try
                            {
                                capturedAction?.Invoke();
                            }
                            catch (Exception ex)
                            {
                                Log($"[HOTKEY ERROR] Key={key}: {ex.Message}");
                            }
                        });

                        Log($"[HOTKEY] Key={key}, Alt={alt}");
                        return (IntPtr)1; // Consume the key
                    }
                }
            }
            catch
            {
                // Never let exceptions escape the hook callback
            }

            return CallNextHookEx(_hookId, nCode, wParam, lParam);
        }

        public void Dispose()
        {
            if (_hookId != IntPtr.Zero)
            {
                UnhookWindowsHookEx(_hookId);
                Log("[HotkeyManager] Hook removed");
                _hookId = IntPtr.Zero;
            }

            if (_gcHandle.IsAllocated)
            {
                _gcHandle.Free();
            }

            _altActions.Clear();
        }
    }
}

