private void RegisterGlobalHotkeys()
{
    void Reg(Keys k, Action uiAction)
    {
        // The action will be invoked from ThreadPool by HotkeyManager.
        // We use BeginInvoke to post to the UI thread without blocking.
        _hotkeyManager.Register(NativeMethods.MOD_ALT, k, () =>
        {
            Dispatcher.BeginInvoke(uiAction);
        });
    }

    // Alt+Z: Toggle Visibility
    Reg(Keys.Z, () => _windowManager.ToggleVisibility());

    // Alt+X: Toggle Ghost Mode
    Reg(Keys.X, () =>
    {
        _windowManager.ToggleGhostMode();
        SendJsonToWeb("ghost_mode_toggled", new { is_ghost = _windowManager.IsGhostMode });
    });

    // Alt+1/2/3: Transparency Presets
    Reg(Keys.D1, () => ApplyOpacity(0.40));
    Reg(Keys.D2, () => ApplyOpacity(0.70));
    Reg(Keys.D3, () => ApplyOpacity(1.00));
    Reg(Keys.NumPad1, () => ApplyOpacity(0.40));
    Reg(Keys.NumPad2, () => ApplyOpacity(0.70));
    Reg(Keys.NumPad3, () => ApplyOpacity(1.00));

    // Alt+[ / Alt+]: Step transparency down/up
    Reg(Keys.OemOpenBrackets, () => ApplyOpacity(this.Opacity - 0.15));
    Reg(Keys.OemCloseBrackets, () => ApplyOpacity(this.Opacity + 0.15));
    Reg(Keys.Oem4, () => ApplyOpacity(this.Opacity - 0.15));
    Reg(Keys.Oem6, () => ApplyOpacity(this.Opacity + 0.15));

    // Alt+Q/W/E: AI Presets
    Reg(Keys.Q, () =>
    {
        _sessionController.Llm.ActivePreset = "primary";
        SendJsonToWeb("preset_switched", new { preset = "primary" });
    });
    Reg(Keys.W, () =>
    {
        _sessionController.Llm.ActivePreset = "secondary";
        SendJsonToWeb("preset_switched", new { preset = "secondary" });
    });
    Reg(Keys.E, () =>
    {
        _sessionController.Llm.ActivePreset = "auto";
        SendJsonToWeb("preset_switched", new { preset = "auto" });
    });

    // Alt+S: Capture Screenshot
    Reg(Keys.S, () =>
    {
        _sessionController.Vision.CaptureScreen();
        SendJsonToWeb("screenshot_queued", new { count = _sessionController.Vision.QueueCount });
    });

    // Alt+P: Process Screenshots with AI
    Reg(Keys.P, async () =>
    {
        await _sessionController.ProcessVisionAnalysisAsync("", "", new List<string>());
    });

    // Alt+R: Reset Screenshot Queue
    Reg(Keys.R, () =>
    {
        _sessionController.Vision.ClearQueue();
        SendJsonToWeb("screenshot_queued", new { count = 0 });
    });

    // Alt+T: Switch Vision Model
    Reg(Keys.T, () => SendJsonToWeb("switch_vision_model", new { }));

    // Alt+M: Toggle Mic Mute
    Reg(Keys.M, () =>
    {
        _sessionController.Audio.IsMuted = !_sessionController.Audio.IsMuted;
