private void RegisterGlobalHotkeys()
{
    void RegisterAlt(Keys k, Action a)
    {
        _hotkeyManager.Register(NativeMethods.MOD_ALT, k, a);
    }

    // Alt+Z: Toggle Visibility
    RegisterAlt(Keys.Z, () => Dispatcher.Invoke(() => _windowManager.ToggleVisibility()));

    // Alt+X: Toggle Ghost Mode
    RegisterAlt(Keys.X, () => Dispatcher.Invoke(() =>
    {
        _windowManager.ToggleGhostMode();
        SendJsonToWeb("ghost_mode_toggled", new { is_ghost = _windowManager.IsGhostMode });
    }));

    // Alt+1/2/3: Transparency Presets
    RegisterAlt(Keys.D1, () => SetWindowOpacity(0.40));
    RegisterAlt(Keys.D2, () => SetWindowOpacity(0.70));
    RegisterAlt(Keys.D3, () => SetWindowOpacity(1.00));
    RegisterAlt(Keys.NumPad1, () => SetWindowOpacity(0.40));
    RegisterAlt(Keys.NumPad2, () => SetWindowOpacity(0.70));
    RegisterAlt(Keys.NumPad3, () => SetWindowOpacity(1.00));

    // Alt+[ and Alt+]: Step transparency down/up
    RegisterAlt(Keys.OemOpenBrackets, () => AdjustTransparency(-0.15));
    RegisterAlt(Keys.OemCloseBrackets, () => AdjustTransparency(+0.15));
    RegisterAlt(Keys.Oem4, () => AdjustTransparency(-0.15));
    RegisterAlt(Keys.Oem6, () => AdjustTransparency(+0.15));
    RegisterAlt(Keys.Oemtilde, () => AdjustTransparency(-0.15));
    RegisterAlt(Keys.OemQuotes, () => AdjustTransparency(+0.15));

    // Alt+Q/W/E: AI Presets (Primary, Secondary, Auto)
    RegisterAlt(Keys.Q, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Llm.ActivePreset = "primary";
        SendJsonToWeb("preset_switched", new { preset = "primary" });
    }));
    RegisterAlt(Keys.W, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Llm.ActivePreset = "secondary";
        SendJsonToWeb("preset_switched", new { preset = "secondary" });
    }));
    RegisterAlt(Keys.E, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Llm.ActivePreset = "auto";
        SendJsonToWeb("preset_switched", new { preset = "auto" });
    }));

    // Alt+S: Capture Screenshot
    RegisterAlt(Keys.S, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Vision.CaptureScreen();
        SendJsonToWeb("screenshot_queued", new { count = _sessionController.Vision.QueueCount });
    }));

    // Alt+P: Process Screenshots with AI
    RegisterAlt(Keys.P, () => Dispatcher.Invoke(async () =>
    {
        await _sessionController.ProcessVisionAnalysisAsync("", "", new List<string>());
    }));

    // Alt+R: Reset Screenshot Queue
    RegisterAlt(Keys.R, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Vision.ClearQueue();
        SendJsonToWeb("screenshot_queued", new { count = 0 });
    }));

    // Alt+T: Switch Vision Model
    RegisterAlt(Keys.T, () => Dispatcher.Invoke(() => SendJsonToWeb("switch_vision_model", new { })));

    // Alt+M: Toggle Mic Mute
    RegisterAlt(Keys.M, () => Dispatcher.Invoke(() =>
    {
        _sessionController.Audio.IsMuted = !_sessionController.Audio.IsMuted;
        SendJsonToWeb("mute_state_changed", new { is_muted = _sessionController.Audio.IsMuted });
    }));

    // Alt+U: Toggle Universal Mute (Pause)
    RegisterAlt(Keys.U, () => Dispatcher.Invoke(() => SendJsonToWeb("toggle_universal_mute", new { })));

    // Alt+O: Reset Interview Session
    RegisterAlt(Keys.O, () => Dispatcher.Invoke(() =>
    {
        _sessionController.ResetSession();
        SendJsonToWeb("session_reset", new { status = "ok" });
    }));

    // Movement Hotkeys: Alt+I/J/Left/Right
    RegisterAlt(Keys.I, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(0, -20)));
    RegisterAlt(Keys.J, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(0, 20)));
    RegisterAlt(Keys.Left, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(-20, 0)));
    RegisterAlt(Keys.Right, () => Dispatcher.Invoke(() => _windowManager.MoveWindow(20, 0)));

    // Scroll Hotkeys: Alt+Up/Down
    RegisterAlt(Keys.Up, () => ScrollWebContent(-100));
    RegisterAlt(Keys.Down, () => ScrollWebContent(100));
}

private void ScrollWebContent(int deltaY)
{
    Dispatcher.Invoke(() =>
    {
        if (WebView != null && WebView.CoreWebView2 != null)
        {
            WebView.CoreWebView2.ExecuteScriptAsync($"window.scrollBy({{ top: {deltaY}, behavior: 'smooth' }});");
        }
    });
}

public void SetWindowOpacity(double opacity)
{
    Dispatcher.Invoke(() =>
    {
        opacity = Math.Clamp(opacity, 0.2, 1.0);
        this.Opacity = opacity;
        _windowManager.SetTransparency(opacity);
        SendJsonToWeb("transparency_changed", new { transparency = opacity, percent = (int)(opacity * 100) });
    });
}

public void AdjustTransparency(double delta)
{
    Dispatcher.Invoke(() =>
    {
        double next = Math.Clamp(_windowManager.CurrentTransparency + delta, 0.2, 1.0);
        SetWindowOpacity(next);
    });
}

