        _sessionController.ResetSession();
        SendJsonToWeb("session_reset", new { status = "ok" });
    });

    // Movement Hotkeys
    Reg(Keys.I, () => _windowManager.MoveWindow(0, -20));
    Reg(Keys.J, () => _windowManager.MoveWindow(0, 20));
    Reg(Keys.Left, () => _windowManager.MoveWindow(-20, 0));
    Reg(Keys.Right, () => _windowManager.MoveWindow(20, 0));

    // Scroll
    Reg(Keys.Up, () =>
    {
        if (WebView?.CoreWebView2 != null)
            WebView.CoreWebView2.ExecuteScriptAsync("window.scrollBy({top:-100,behavior:'smooth'});");
    });
    Reg(Keys.Down, () =>
    {
        if (WebView?.CoreWebView2 != null)
            WebView.CoreWebView2.ExecuteScriptAsync("window.scrollBy({top:100,behavior:'smooth'});");
    });
}

private void ApplyOpacity(double opacity)
{
    opacity = Math.Clamp(opacity, 0.20, 1.0);
    bool success = _windowManager.SetTransparency(opacity);
    File.AppendAllText(LogPath, $"[OPACITY] Set to {opacity:F2} ({(int)(opacity*100)}%), Win32Result={success}\n");
    SendJsonToWeb("transparency_changed", new { transparency = opacity, percent = (int)(opacity * 100) });
}

// Keep for IPC compatibility
public void SetWindowOpacity(double opacity)
{
    Dispatcher.BeginInvoke(() => ApplyOpacity(opacity));
}

public void AdjustTransparency(double delta)
{
    Dispatcher.BeginInvoke(() => ApplyOpacity(_windowManager.CurrentTransparency + delta));
}

