/// <summary>
/// Set the entire window opacity using WPF's DWM composition.
/// This works with WebView2 because DWM applies opacity to the entire
/// window surface including child HWNDs. No Win32 hacks needed.
/// </summary>
private void ApplyOpacity(double opacity)
{
    opacity = Math.Clamp(opacity, 0.20, 1.0);
    this.Opacity = opacity;
    _windowManager.SetTransparency(opacity); // store the value
    File.AppendAllText(LogPath, $"[OPACITY] Set to {opacity:F2} ({(int)(opacity*100)}%)\n");
