// Prompt builder matching Spectra interview intelligence
function buildCandidateProfile(profile = {}) {
    const parts = [];
    if (profile.candidate_name) parts.push(`Candidate Name: ${profile.candidate_name}`);
    if (profile.target_company) parts.push(`Target Company: ${profile.target_company}`);
    if (profile.target_role) parts.push(`Target Role: ${profile.target_role}`);
    if (profile.focus_areas && profile.focus_areas.length) {
        parts.push(`Interview Focus Areas: ${profile.focus_areas.join(', ')}`);
    }
    if (profile.complete_resume) {
        parts.push(`COMPLETE RESUME/BACKGROUND:\n${profile.complete_resume}`);
    }
    if (profile.complete_job_description) {
        parts.push(`COMPLETE JOB DESCRIPTION/REQUIREMENTS:\n${profile.complete_job_description}`);
    }
    return parts.length ? parts.join('\n') + '\n' : '';
}

function getInterviewAnswerPrompt(question, persistentContext = {}, conversationHistory = []) {
    const parts = [];

    parts.push(`You are an expert interview coach providing real-time assistance during a live job interview.
Your goal is to help the candidate give the best possible answer to the interviewer's question.

CRITICAL INSTRUCTIONS:
- Give a direct, high-impact answer. No fluff, no introductory chit-chat.
- If technical/coding: provide clear algorithm steps, complexity (Time & Space), and clean code.
- If behavioral: use the STAR method (Situation, Task, Action, Result) concisely.
- If system design: cover requirements, high-level architecture, key trade-offs, and scaling.
- Keep formatting clean using markdown bullet points and bold headers.`);

    const profileText = buildCandidateProfile(persistentContext);
    if (profileText) {
        parts.push("=================================================================================");
        parts.push("PERSISTENT CANDIDATE CONTEXT:");
        parts.push(profileText);
        parts.push("=================================================================================");
    }

    if (conversationHistory && conversationHistory.length > 0) {
        parts.push("RECENT CONVERSATION HISTORY:");
        const recent = conversationHistory.slice(-5);
        recent.forEach((item, idx) => {
            if (item.interviewer_question) parts.push(`Q${idx + 1}: ${item.interviewer_question}`);
            if (item.ai_response) parts.push(`A${idx + 1}: ${item.ai_response.slice(0, 300)}...`);
        });
        parts.push("=================================================================================");
    }

    parts.push(`CURRENT INTERVIEWER QUESTION:
"${question}"

Provide the answer for the candidate to speak right now:`);

    return parts.join('\n\n');
}

function getVisionPrompt(userPrompt, persistentContext = {}) {
    return `You are an expert technical interview assistant analyzing a screen capture from a live interview or coding test.
The candidate needs quick, accurate, actionable help.

${userPrompt ? `USER REQUEST: "${userPrompt}"` : 'Analyze the code or problem shown on the screen, identify any bugs, provide the optimal solution, and explain clearly.'}

Format your answer with clean markdown, code snippets, and complexity analysis.`;
}

module.exports = {
    buildCandidateProfile,
    getInterviewAnswerPrompt,
    getVisionPrompt
};

const OpenAI = require('openai');

class LLMService {
    constructor(providerConfig) {
        this.name = providerConfig.name;
        this.baseURL = providerConfig.baseURL;
        this.model = providerConfig.defaultModel || (providerConfig.models && providerConfig.models[0]?.modelName);
        this.requestParams = providerConfig.requestParams || {};

        // Filter out placeholders
        const rawKeys = providerConfig.apiKeys && providerConfig.apiKeys.length 
            ? providerConfig.apiKeys 
            : [providerConfig.apiKey];

        this.apiKeys = rawKeys.filter(k => k && !k.includes('YOUR_') && !k.includes('_HERE'));
        this.keyIndex = 0;
        this.client = null;
        this.initClient();
    }

    initClient() {
        const key = this.apiKeys[this.keyIndex] || '';
        if (key) {
            this.client = new OpenAI({
                baseURL: this.baseURL,
                apiKey: key,
                dangerouslyAllowBrowser: false
            });
        } else {
            this.client = null;
        }
    }

    rotateKey() {
        if (this.apiKeys.length <= 1) return;
        this.keyIndex = (this.keyIndex + 1) % this.apiKeys.length;
        console.log(`[LLM] Rotating key for ${this.name} -> index ${this.keyIndex}`);
        this.initClient();
    }

    async verifyConnection(modelName) {
        if (!this.client) return false;
        try {
            const testModel = modelName || this.model;
            const resp = await this.client.chat.completions.create({
                model: testModel,
                messages: [{ role: 'user', content: 'hi' }],
                max_tokens: 5
            });
            return Boolean(resp && resp.choices);
        } catch (err) {
            console.error(`[LLM] Verification error for ${this.name}:`, err.message);
            return false;
        }
    }

    async streamAnswer(prompt, onChunk, maxTokens = 2048) {
        if (!this.client) {
            throw new Error(`Provider ${this.name} has no valid API key configured.`);
        }

        let attempts = 0;
        const maxAttempts = Math.max(1, this.apiKeys.length);

        while (attempts < maxAttempts) {
            try {
                const stream = await this.client.chat.completions.create({
                    model: this.model,
                    messages: [
                        { role: 'user', content: prompt }
                    ],
                    stream: true,
                    max_tokens: maxTokens,
                    temperature: 0.6,
                    ...this.requestParams
                });

                let fullText = '';
                for await (const chunk of stream) {
                    const text = chunk.choices[0]?.delta?.content || '';
                    if (text) {
                        fullText += text;
                        if (onChunk) onChunk(text);
                    }
                }
                return fullText;
            } catch (err) {
                console.warn(`[LLM] Error with ${this.name} (key index ${this.keyIndex}):`, err.message);
                attempts++;
                if (this.apiKeys.length > 1) {
                    this.rotateKey();
                } else {
                    throw err;
                }
            }
        }
        throw new Error(`All keys exhausted for provider ${this.name}`);
    }

    async streamVision(prompt, base64Images = [], onChunk) {
        if (!this.client) {
            throw new Error(`Vision provider ${this.name} has no valid API key.`);
        }

        const content = [{ type: 'text', text: prompt }];
        for (const img of base64Images) {
            const url = img.startsWith('data:') ? img : `data:image/jpeg;base64,${img}`;
            content.push({
                type: 'image_url',
                image_url: { url }
            });
        }

        const stream = await this.client.chat.completions.create({
            model: this.model,
            messages: [{ role: 'user', content }],
            stream: true,
            max_tokens: 2500,
            temperature: 0.5
        });

        let fullText = '';
        for await (const chunk of stream) {
            const text = chunk.choices[0]?.delta?.content || '';
            if (text) {
                fullText += text;
                if (onChunk) onChunk(text);
            }
        }
        return fullText;
    }
}

module.exports = { LLMService };

const WebSocket = require('ws');

class DeepgramLiveSTT {
    constructor(apiKey, onTranscript) {
        this.apiKey = apiKey;
        this.onTranscript = onTranscript;
        this.ws = null;
        this.isConnected = false;
        this.queue = [];
    }

    connect() {
        if (!this.apiKey || this.apiKey.includes('YOUR_')) {
            console.warn('[STT] No valid Deepgram API key provided.');
            return;
        }

        const url = 'wss://api.deepgram.com/v1/listen?encoding=linear16&sample_rate=16000&channels=1&model=nova-2&punctuate=true&interim_results=true&smart_format=true';
        this.ws = new WebSocket(url, {
            headers: {
                Authorization: `Token ${this.apiKey}`
            }
        });

        this.ws.on('open', () => {
            this.isConnected = true;
            console.log('[STT] Connected to Deepgram Live Transcription');
            while (this.queue.length > 0) {
                const chunk = this.queue.shift();
                this.ws.send(chunk);
            }
        });

        this.ws.on('message', (data) => {
            try {
                const msg = JSON.parse(data.toString());
                if (msg.channel && msg.channel.alternatives && msg.channel.alternatives.length > 0) {
                    const alt = msg.channel.alternatives[0];
                    const transcript = alt.transcript;
                    const isFinal = msg.is_final || false;
                    const speaker = (alt.words && alt.words[0]?.speaker !== undefined) ? alt.words[0].speaker : 0;

                    if (transcript && transcript.trim().length > 0) {
                        this.onTranscript({
                            transcript: transcript.trim(),
                            is_final: isFinal,
                            speaker: speaker
                        });
                    }
                }
            } catch (err) {
                console.error('[STT] Error parsing Deepgram message:', err);
            }
        });

        this.ws.on('close', () => {
            this.isConnected = false;
            console.log('[STT] Deepgram connection closed.');
        });

        this.ws.on('error', (err) => {
            console.error('[STT] Deepgram error:', err.message);
        });
    }

    sendAudio(buffer) {
        if (this.isConnected && this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(buffer);
        } else {
            if (this.queue.length < 50) {
                this.queue.push(buffer);
            }
        }
    }

    close() {
        if (this.ws) {
            try {
                this.ws.close();
            } catch (e) {}
            this.ws = null;
            this.isConnected = false;
        }
    }
}

async function verifyDeepgramKey(apiKey) {
    if (!apiKey || apiKey.includes('YOUR_')) return false;
    try {
        const resp = await fetch('https://api.deepgram.com/v1/projects', {
            headers: { Authorization: `Token ${apiKey}` }
        });
        return resp.status === 200;
    } catch (e) {
        return false;
    }
}

module.exports = {
    DeepgramLiveSTT,
    verifyDeepgramKey
};

const { LLMService } = require('./llm');
const { DeepgramLiveSTT, verifyDeepgramKey } = require('./stt');
const { getInterviewAnswerPrompt, getVisionPrompt } = require('./prompts');

class InterviewSession {
    constructor(sessionId, sendJsonCallback) {
        this.sessionId = sessionId;
        this.sendJson = sendJsonCallback;

        this.primaryLLM = null;
        this.secondaryLLM = null;
        this.primaryVision = null;
        this.secondaryVision = null;
        this.activePreset = 'Primary';

        this.stt = null;
        this.deepgramApiKey = process.env.DEEPGRAM_API_KEY || '';

        this.persistentContext = {};
        this.conversationHistory = [];
        this.state = {
            is_muted: false,
            process_all_speakers: true,
            is_universally_muted: false
        };

        this.currentInterviewerSpeech = '';
        this.silenceTimer = null;
        this.isProcessingAI = false;
    }

    setDeepgramKey(key) {
        this.deepgramApiKey = key;
    }

    async handleVerifyDeepgram(payload) {
        const key = payload?.key || this.deepgramApiKey;
        const valid = await verifyDeepgramKey(key);
        this.sendJson('api_key_status', { service: 'deepgram', valid });
    }

    async handleStartInterview(payload) {
        try {
            console.log(`[Session ${this.sessionId}] Initializing interview providers...`);
            this.state.is_muted = payload.is_muted || false;
            this.state.process_all_speakers = payload.process_all_speakers !== false;
            this.state.is_universally_muted = payload.is_universally_muted || false;
            this.persistentContext = payload.onboardingData || {};

            if (payload.aiProvider) {
                this.primaryLLM = new LLMService(payload.aiProvider);
            }
            if (payload.aiSecondaryProvider) {
                this.secondaryLLM = new LLMService(payload.aiSecondaryProvider);
            }
            if (payload.visionProvider) {
                this.primaryVision = new LLMService(payload.visionProvider);
            }
            if (payload.visionSecondaryProvider) {
                this.secondaryVision = new LLMService(payload.visionSecondaryProvider);
            }

            // Start STT
            if (this.stt) {
                this.stt.close();
            }
            this.stt = new DeepgramLiveSTT(this.deepgramApiKey, (data) => this.onTranscript(data));
            this.stt.connect();

            // Health checks
            const healthResults = {
                primary: this.primaryLLM ? Boolean(this.primaryLLM.client) : false,
                secondary: this.secondaryLLM ? Boolean(this.secondaryLLM.client) : false
            };

            this.sendJson('preset_initialized', {
                current_preset: 'Primary',
                available_presets: ['Primary', 'Secondary'],
                health_status: healthResults
            });
            console.log(`[Session ${this.sessionId}] Interview started successfully.`);
        } catch (err) {
            console.error(`[Session ${this.sessionId}] Error starting interview:`, err);
            this.sendJson('error', { message: `Failed to initialize: ${err.message}` });
        }
    }

    onTranscript(data) {
        const { transcript, is_final, speaker } = data;
        this.sendJson('transcript_update', {
            transcript,
            is_final,
            speaker
        });

        if (this.state.is_universally_muted) return;

        if (is_final) {
            this.currentInterviewerSpeech += ' ' + transcript;
            this.resetSilenceTimer();
        }
    }

    resetSilenceTimer() {
        if (this.silenceTimer) {
            clearTimeout(this.silenceTimer);
        }

        // Trigger AI after 1.8 seconds of silence following interviewer speech
        this.silenceTimer = setTimeout(() => {
            const question = this.currentInterviewerSpeech.trim();
            if (question.length > 5 && !this.isProcessingAI) {
                this.currentInterviewerSpeech = '';
                this.triggerAIAnswer(question);
            }
        }, 1800);
    }

    async triggerAIAnswer(question) {
        this.isProcessingAI = true;
        const llm = (this.activePreset === 'Secondary' && this.secondaryLLM) ? this.secondaryLLM : this.primaryLLM;

        if (!llm) {
            this.sendJson('error', { message: 'No AI provider active for interview answers.' });
            this.isProcessingAI = false;
            return;
        }

        const prompt = getInterviewAnswerPrompt(question, this.persistentContext, this.conversationHistory);
        this.sendJson('ai_processing_started', { prompt: question });

        const startTime = Date.now();
        let fullAnswer = '';

        try {
            fullAnswer = await llm.streamAnswer(prompt, (chunk) => {
                this.sendJson('ai_answer_chunk', { chunk });
            });

            const durationMs = Date.now() - startTime;
            this.conversationHistory.push({
                interviewer_question: question,
                ai_response: fullAnswer
            });

            this.sendJson('ai_answer_complete', {
                full_answer: fullAnswer,
                duration_ms: durationMs
            });
        } catch (err) {
            console.error('[Session] AI Answer generation failed:', err.message);
            this.sendJson('error', { message: `AI error: ${err.message}` });
        } finally {
            this.isProcessingAI = false;
        }
    }

    handleAudioChunk(payload) {
        if (!this.stt || this.state.is_universally_muted) return;
        const b64 = payload.audio_b64;
        if (b64) {
            try {
                const buffer = Buffer.from(b64, 'base64');
                this.stt.sendAudio(buffer);
            } catch (err) {
                console.warn('[Session] Invalid audio chunk:', err.message);
            }
        }
    }

    async handleAnalyzeVision(payload) {
        const { images = [], prompt = '' } = payload;
        const visionService = (this.activePreset === 'Secondary' && this.secondaryVision) 
            ? this.secondaryVision 
            : (this.primaryVision || this.primaryLLM);

        if (!visionService) {
            this.sendJson('error', { message: 'No vision provider configured.' });
            return;
        }

        this.sendJson('ai_processing_started', { prompt: prompt || 'Screen analysis' });
        const visionPrompt = getVisionPrompt(prompt, this.persistentContext);
        const startTime = Date.now();

        try {
            const answer = await visionService.streamVision(visionPrompt, images, (chunk) => {
                this.sendJson('ai_answer_chunk', { chunk });
            });

            this.sendJson('ai_answer_complete', {
                full_answer: answer,
                duration_ms: Date.now() - startTime
            });
        } catch (err) {
            console.error('[Session] Vision analysis failed:', err.message);
            this.sendJson('error', { message: `Vision error: ${err.message}` });
        }
    }

    handleSwitchPreset(payload) {
        const target = payload.preset || 'Primary';
        this.activePreset = target;
        this.sendJson('preset_switched', {
            current_preset: target,
            preset_name: target
        });
    }

    handleResetSession() {
        this.conversationHistory = [];
        this.currentInterviewerSpeech = '';
        if (this.silenceTimer) clearTimeout(this.silenceTimer);
        this.isProcessingAI = false;
        this.sendJson('session_reset_complete', {});
    }

    destroy() {
        if (this.silenceTimer) clearTimeout(this.silenceTimer);
        if (this.stt) this.stt.close();
    }
}

module.exports = { InterviewSession };

const path = require('path');
const fs = require('fs');
const http = require('http');
const express = require('express');
const cors = require('cors');
const { WebSocketServer } = require('ws');
const dotenv = require('dotenv');
const { InterviewSession } = require('./session');
const { verifyDeepgramKey } = require('./stt');
const { LLMService } = require('./llm');

dotenv.config();

function createServer(options = {}) {
    const app = express();
    app.use(cors());
    app.use(express.json({ limit: '50mb' }));

    const rootDir = path.resolve(__dirname, '../../');
    const webDir = path.join(rootDir, 'web');
    const providersPath = path.join(rootDir, 'ai_providers.json');
    const exampleProvidersPath = path.join(rootDir, 'ai_providers.example.json');

    // Serve static frontend files
    app.use(express.static(webDir));
    app.use('/css', express.static(path.join(webDir, 'css')));
    app.use('/js', express.static(path.join(webDir, 'js')));
    app.use('/static', express.static(webDir));

    function getProvidersData() {
        if (!fs.existsSync(providersPath)) {
            if (fs.existsSync(exampleProvidersPath)) {
                fs.copyFileSync(exampleProvidersPath, providersPath);
            } else {
                return [];
            }
        }
        try {
            return JSON.parse(fs.readFileSync(providersPath, 'utf8'));
        } catch (e) {
            console.error('Error reading ai_providers.json:', e);
            return [];
        }
    }

    // Config route
    app.get('/api/config', (req, res) => {
        res.json({
            DEV_MODE: false,
            LOG_LEVEL: 'INFO',
            CAPTURE_PROTECTION_ENABLED: true
        });
    });

    // AI Providers - Sanitized for general client view
    app.get('/api/ai-providers', (req, res) => {
        const providers = getProvidersData();
        const safe = providers.map(p => ({
            name: p.name,
            models: p.models || [],
            visionModels: p.visionModels || [],
            supportsVision: p.supportsVision || false,
            maxImages: p.maxImages || 2,
            defaultPrimary: p.defaultPrimary || false,
            defaultSecondary: p.defaultSecondary || false,
            defaultVisionPrimary: p.defaultVisionPrimary || false,
            defaultVisionSecondary: p.defaultVisionSecondary || false,
            defaultModel: p.defaultModel,
            defaultVisionModel: p.defaultVisionModel
        }));
        res.json(safe);
    });

    // AI Providers - Full (with keys for settings modal)
    app.get('/api/ai-providers/full', (req, res) => {
        const providers = getProvidersData();
        res.json(providers);
    });

    // Deepgram Key
    app.get('/api/deepgram-key', (req, res) => {
        const key = process.env.DEEPGRAM_API_KEY || '';
        res.json({ key });
    });

    // Save Deepgram Key
    app.post('/api/save-deepgram-key', (req, res) => {
        const { key } = req.body;
        if (key !== undefined) {
            process.env.DEEPGRAM_API_KEY = key;
            const envPath = path.join(rootDir, '.env');
            let envContent = fs.existsSync(envPath) ? fs.readFileSync(envPath, 'utf8') : '';
            if (envContent.includes('DEEPGRAM_API_KEY=')) {
                envContent = envContent.replace(/DEEPGRAM_API_KEY=.*/, `DEEPGRAM_API_KEY=${key}`);
            } else {
                envContent += `\nDEEPGRAM_API_KEY=${key}\n`;
            }
            fs.writeFileSync(envPath, envContent);
            return res.json({ success: true, message: 'Deepgram key saved.' });
        }
        res.status(400).json({ error: 'No key provided' });
    });

    // Save AI Providers
    app.post('/api/save-ai-providers', (req, res) => {
        const { providers } = req.body;
        if (Array.isArray(providers)) {
            fs.writeFileSync(providersPath, JSON.stringify(providers, null, 4));
            return res.json({ success: true, message: 'Providers updated.' });
        }
        res.status(400).json({ error: 'Invalid providers payload' });
    });

    // Verify Provider
    app.post('/api/verify-provider', async (req, res) => {
        const { name, model } = req.body;
        const providers = getProvidersData();
        const prov = providers.find(p => p.name === name);
        if (!prov) {
            return res.status(404).json({ valid: false, message: 'Provider not found' });
        }
        const service = new LLMService(prov);
        const valid = await service.verifyConnection(model);
        res.json({ valid });
    });

    // Verify Vision Provider
    app.post('/api/verify-vision-provider', async (req, res) => {
        const { name, model } = req.body;
        const providers = getProvidersData();
        const prov = providers.find(p => p.name === name);
        if (!prov) {
            return res.status(404).json({ valid: false, message: 'Vision provider not found' });
        }
        const service = new LLMService(prov);
        const valid = await service.verifyConnection(model);
        res.json({ valid });
    });

    // Native Silent Screenshot endpoint
    app.post('/api/screenshot/native', async (req, res) => {
        if (options.captureNativeScreenshot) {
            try {
                const result = await options.captureNativeScreenshot();
                return res.json(result);
            } catch (err) {
                console.error('[Screenshot] Error:', err);
                return res.status(500).json({ success: false, detail: err.message });
            }
        }
        res.status(501).json({ success: false, detail: 'Native screenshot handler not bound.' });
    });

    // Transparency endpoints
    app.post('/api/transparency', (req, res) => {
        const { transparency } = req.body;
        if (typeof transparency === 'number' && options.setOpacity) {
            options.setOpacity(Math.max(0.1, Math.min(1.0, transparency)));
            return res.json({ success: true, opacity: transparency });
        }
        res.json({ success: true });
    });

    app.post('/api/transparency/percent', (req, res) => {
        const { percent } = req.body;
        if (typeof percent === 'number' && options.setOpacity) {
            options.setOpacity(Math.max(0.1, Math.min(1.0, percent / 100)));
            return res.json({ success: true, percent });
        }
        res.json({ success: true });
    });

    app.post('/api/window/always-on-top', (req, res) => {
        const { always_on_top } = req.body;
        if (options.setAlwaysOnTop) {
            options.setAlwaysOnTop(Boolean(always_on_top));
        }
        res.json({ success: true });
    });

    const server = http.createServer(app);
    const wss = new WebSocketServer({ server, path: '/ws' });

    const activeSessions = new Map();

    wss.on('connection', (ws) => {
        const sessionId = 'session_' + Math.random().toString(36).substring(2, 9);
        const sendJson = (type, payload) => {
            if (ws.readyState === ws.OPEN) {
                ws.send(JSON.stringify({ type, payload }));
            }
        };

        const session = new InterviewSession(sessionId, sendJson);
        activeSessions.set(sessionId, session);

        sendJson('session_created', { session_id: sessionId });

        ws.on('message', async (data) => {
            try {
                const message = JSON.parse(data.toString());
                const type = message.type;
                const payload = message.payload || {};

                switch (type) {
                    case 'verify_deepgram':
                        await session.handleVerifyDeepgram(payload);
                        break;
                    case 'start_interview':
                        await session.handleStartInterview(payload);
                        break;
                    case 'audio_chunk':
                        session.handleAudioChunk(payload);
                        break;
                    case 'analyze_vision':
                        await session.handleAnalyzeVision(payload);
                        break;
                    case 'switch_preset':
                        session.handleSwitchPreset(payload);
                        break;
                    case 'reset_session':
                        session.handleResetSession();
                        break;
                    default:
                        console.warn(`[WS] Unknown message type: ${type}`);
                }
            } catch (err) {
                console.error('[WS] Message handling error:', err);
            }
        });

        ws.on('close', () => {
            session.destroy();
            activeSessions.delete(sessionId);
        });
    });

    return { server, app };
}

module.exports = { createServer };

const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('spectraAPI', {
    toggleGhostMode: () => ipcRenderer.send('toggle-ghost-mode'),
    panicCloak: () => ipcRenderer.send('panic-cloak'),
    setOpacity: (opacity) => ipcRenderer.send('set-opacity', opacity),
    captureScreen: () => ipcRenderer.invoke('capture-screen')
});

const { app, BrowserWindow, globalShortcut, desktopCapturer, screen, ipcMain } = require('electron');
const path = require('path');
const { createServer } = require('./server/server');

// Process disguise
process.title = 'NetworkAdapter';

let mainWindow = null;
let currentOpacity = 0.95;
let isGhostMode = false;
let isPanicHidden = false;

// Native screen capture implementation using Electron's desktopCapturer
async function captureNativeScreenshot() {
    try {
        const primaryDisplay = screen.getPrimaryDisplay();
        const { width, height } = primaryDisplay.bounds;

        const sources = await desktopCapturer.getSources({
            types: ['screen'],
            thumbnailSize: { width: Math.min(width, 1920), height: Math.min(height, 1080) }
        });

        if (!sources || sources.length === 0) {
            throw new Error('No screen capture sources available.');
        }

        const primarySource = sources[0];
        const dataUrl = primarySource.thumbnail.toDataURL();
        const size = primarySource.thumbnail.getSize();

        return {
            success: true,
            dataUrl,
            width: size.width,
            height: size.height
        };
    } catch (err) {
        console.error('[Capture] Screen capture failed:', err);
        throw err;
    }
}

function createWindow(port) {
    const primaryDisplay = screen.getPrimaryDisplay();
    const { width, height } = primaryDisplay.workAreaSize;

    // Window options matching Parakeet AI 1:1
    mainWindow = new BrowserWindow({
        width: Math.min(1450, width),
        height: Math.min(920, height),
        x: Math.floor((width - Math.min(1450, width)) / 2),
        y: 40,
        transparent: true,
        frame: false,
        alwaysOnTop: true,
        skipTaskbar: true,
        resizable: false,
        hasShadow: false,
        roundedCorners: false,
        type: 'panel',
        webPreferences: {
            preload: path.join(__dirname, 'preload.js'),
            contextIsolation: true,
            nodeIntegration: false,
            backgroundThrottling: false,
            spellcheck: false
        }
    });

    // 1:1 Parakeet AI Anti-Proctoring: Hardware-level Screen Capture Exclusion (WDA_EXCLUDEFROMCAPTURE)
    mainWindow.setContentProtection(true);

    // Initial opacity
    mainWindow.setOpacity(currentOpacity);

    // Set level to ensure always-on-top above full-screen browsers
    mainWindow.setAlwaysOnTop(true, 'screen-saver');

    // Load web interface from embedded local server
    mainWindow.loadURL(`http://127.0.0.1:${port}`);

    mainWindow.on('closed', () => {
        mainWindow = null;
    });

    // Register Global Shortcuts (1:1 operational ergonomics)
    registerShortcuts();
}

function toggleGhostMode() {
    if (!mainWindow) return;
    isGhostMode = !isGhostMode;
    // Parakeet 1:1: setIgnoreMouseEvents with forward: true for click-through
    mainWindow.setIgnoreMouseEvents(isGhostMode, { forward: true });
    console.log(`[Stealth] Ghost Mode (click-through): ${isGhostMode ? 'ENABLED' : 'DISABLED'}`);
}

function panicCloak() {
    if (!mainWindow) return;
    if (isPanicHidden) {
        mainWindow.show();
        mainWindow.setOpacity(currentOpacity);
        isPanicHidden = false;
        console.log('[Stealth] Restoring from Panic Cloak');
    } else {
        mainWindow.hide();
        isPanicHidden = true;
        console.log('[Stealth] EMERGENCY PANIC CLOAK TRIGGERED - Window hidden');
    }
}

function adjustOpacity(delta) {
    if (!mainWindow) return;
    currentOpacity = Math.max(0.15, Math.min(1.0, currentOpacity + delta));
    mainWindow.setOpacity(currentOpacity);
    console.log(`[Stealth] Opacity adjusted: ${(currentOpacity * 100).toFixed(0)}%`);
}

function registerShortcuts() {
    // Panic cloak hotkeys: Alt+Esc and Alt+`
    globalShortcut.register('Alt+Escape', panicCloak);
    globalShortcut.register('Alt+`', panicCloak);

    // Ghost click-through toggle: Ctrl+Shift+Space and Alt+C
    globalShortcut.register('CommandOrControl+Shift+Space', toggleGhostMode);
    globalShortcut.register('Alt+C', toggleGhostMode);

    // Opacity adjustments: Ctrl+Shift+Up / Down
    globalShortcut.register('CommandOrControl+Shift+Up', () => adjustOpacity(0.1));
    globalShortcut.register('CommandOrControl+Shift+Down', () => adjustOpacity(-0.1));
}

// IPC handlers
ipcMain.on('toggle-ghost-mode', toggleGhostMode);
ipcMain.on('panic-cloak', panicCloak);
ipcMain.on('set-opacity', (event, opacity) => {
    if (mainWindow && typeof opacity === 'number') {
        currentOpacity = opacity;
        mainWindow.setOpacity(opacity);
    }
});
ipcMain.handle('capture-screen', async () => {
    return await captureNativeScreenshot();
});

// App startup
app.whenReady().then(() => {
    const PORT = process.env.PORT || 8002;
    const { server } = createServer({
        captureNativeScreenshot,
        setOpacity: (val) => {
            if (mainWindow) {
                currentOpacity = val;
                mainWindow.setOpacity(val);
            }
        },
        setAlwaysOnTop: (val) => {
            if (mainWindow) {
                mainWindow.setAlwaysOnTop(val, 'screen-saver');
            }
        }
    });

    server.listen(PORT, '127.0.0.1', () => {
        console.log(`[Host] Spectra Electron Server listening on http://127.0.0.1:${PORT}`);
        createWindow(PORT);
    });
});

app.on('window-all-closed', () => {
    globalShortcut.unregisterAll();
    if (process.platform !== 'darwin') {
        app.quit();
    }
});

app.on('will-quit', () => {
    globalShortcut.unregisterAll();
});

