+        case 'top-left':
+            x = workArea.x + margin;
+            y = workArea.y + margin;
+            break;
+        case 'top-center':
+            x = workArea.x + Math.round((workArea.width - finalW) / 2);
+            y = workArea.y + margin;
+            break;
+        case 'top-right':
+            x = workArea.x + workArea.width - finalW - margin;
+            y = workArea.y + margin;
